<?php
declare(strict_types=1);
namespace SimpleMSPDoc\Tests\Integration;
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }

use SimpleMSPDoc\Core\{Actor,HttpException};
use SimpleMSPDoc\Modules\Audit\AuditService;
use SimpleMSPDoc\Modules\Integrations\Action1\{Action1Service,Action1Client,Action1Error,SecretBox,Transport};
final class Action1FakeTransport implements Transport
{
 public array $responses=[];public array $requests=[];
 public function request(string $method,string $url,array $headers,?string $body=null): array {$this->requests[]=compact('method','url','headers','body');if(!$this->responses)throw new \RuntimeException('Unexpected HTTP call');return array_shift($this->responses);}
 public function json(array $data,int $status=200,array $headers=[]): void {$this->responses[]=['status'=>$status,'body'=>json_encode($data),'headers'=>$headers];}
}
final class Action1Test extends DatabaseTestCase
{
 private function setupAddon(): array {$this->schema();$a=new Actor($this->user(),'administrator','staff');$key=base64_encode(random_bytes(32));$box=new SecretBox($key);$http=new Action1FakeTransport();$s=new Action1Service($this->db,new AuditService($this->db),$box,$http);return [$a,$box,$http,$s,$key];}
 private function unthrottle(): void {$this->db->run('UPDATE action1_settings SET next_request_at=0');}
 public function testCredentialsAuthPagingAndSafeErrors(): void {
  [$a,$box,$http,$s]=$this->setupAddon();$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'my-client','client_secret'=>'my-secret']);$stored=json_encode($this->db->one('SELECT * FROM action1_settings'));self::assertStringNotContainsString('my-secret',$stored);$http->json(['access_token'=>'fake-token','expires_in'=>3600]);$http->json(['items'=>[['id'=>'org-1','name'=>'Customer']],'next_page'=>'https://app.action1.com/api/3.0/organizations?from=50&limit=50']);
  try{$s->test($a);self::fail('Expected pacing after auth');}catch(Action1Error $e){self::assertSame(429,$e->status);self::assertGreaterThan(0,$e->retryAfter);}$this->unthrottle();$result=$s->test($a);self::assertSame(1,$result['count']);self::assertCount(2,$http->requests);self::assertStringContainsString('client_secret=my-secret',$http->requests[0]['body']);self::assertStringContainsString('Bearer fake-token',implode(',',$http->requests[1]['headers']));
  $this->unthrottle();$http->json(['items'=>[],'next_page'=>'https://evil.test/api/3.0/organizations?from=50']);try{$s->test($a);self::fail('Foreign pagination accepted');}catch(Action1Error $e){self::assertSame(502,$e->status);}self::assertCount(3,$http->requests);
  $this->unthrottle();$http->json(['details'=>['retry_after'=>40],'developer_message'=>'my-secret fake-token'],429);try{$s->test($a);self::fail('Expected throttle');}catch(Action1Error $e){self::assertGreaterThanOrEqual(40,$e->retryAfter);self::assertStringNotContainsString('my-secret',$e->getMessage());}self::assertStringNotContainsString('my-secret',json_encode($this->db->all('SELECT * FROM audit_events')));
 }
 public function testMappingSyncPreservesManualDataAndNeverRevivesArchivedRecords(): void {
  [$a,$box,$http,$s]=$this->setupAddon();$org=$this->org();$other=$this->org('Other');$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'client','client_secret'=>'secret']);$this->db->run('UPDATE action1_settings SET token_cipher=?,token_expires=?',[$box->seal(['access_token'=>'token'],'token'),time()+3600]);$s->discoverStart($a);$http->json(['items'=>[['id'=>'remote-1','name'=>'Customer']]]);$s->discoverStep($a);$map=$s->map($a,'remote-1',$org,true);
  $s->startSync($a,$map);$this->unthrottle();$http->json(['items'=>[['id'=>'device-1','name'=>'DC01','OS'=>'Windows Server','address'=>'10.0.0.10','last_seen'=>'2026-10-14','status'=>'Online','missing_critical_updates'=>2]]]);$r=$s->syncStep($a,$map);self::assertFalse($r['more']);$record=$this->db->one('SELECT * FROM records');self::assertSame('internal',$record['visibility']);$id=(int)$record['id'];$payload=json_decode($record['payload'],true);$contact=(new \SimpleMSPDoc\Modules\Organizations\ContactService($this->db,new AuditService($this->db)))->create($a,$org,['title'=>'Former contact']);$this->db->run('UPDATE records SET deleted_at=CURRENT_TIMESTAMP WHERE id=?',[$contact]);$payload['contact_id']=$contact;$payload['notes']='Manual notes';$this->db->run("UPDATE records SET title='Manual title',visibility='client',category='Servers',payload=? WHERE id=?",[json_encode($payload),$id]);
  $s->startSync($a,$map);$this->unthrottle();$http->json(['items'=>[['id'=>'device-1','name'=>'Renamed upstream','OS'=>'Windows Server 2025','address'=>'10.0.0.11']]]);$s->syncStep($a,$map);self::assertSame(1,(int)$this->db->one("SELECT COUNT(*) AS n FROM records WHERE type='asset'")['n']);$record=$this->db->one("SELECT * FROM records WHERE type='asset'");self::assertSame('Manual title',$record['title']);self::assertSame('client',$record['visibility']);self::assertSame('Servers',$record['category']);self::assertSame('Manual notes',json_decode($record['payload'],true)['notes']);self::assertStringContainsString('10.0.0.11',$record['search_text']);
  try{$s->map($a,'remote-1',$other,true);self::fail('Remapping imported assets accepted');}catch(HttpException $e){self::assertSame(409,$e->status);}$this->db->run('UPDATE records SET deleted_at=CURRENT_TIMESTAMP WHERE id=?',[$id]);$s->startSync($a,$map);$this->unthrottle();$http->json(['items'=>[['id'=>'device-1','name'=>'DC01']]]);$r=$s->syncStep($a,$map);self::assertSame(1,$r['skipped']);self::assertNotNull($this->db->one('SELECT deleted_at FROM records WHERE id=?',[$id])['deleted_at']);
  $reader=new Actor($this->user('read-only'),'read-only','staff');$this->expectException(HttpException::class);$s->test($reader);
 }
 public function testSyncWaitingForTemplateLockPreservesTheCommittedManualEdit(): void {
  [$a,$box,$http,$s,$key]=$this->setupAddon();$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'client','client_secret'=>'secret']);$this->db->run('UPDATE action1_settings SET token_cipher=?,token_expires=?',[$box->seal(['access_token'=>'token'],'token'),time()+3600]);$s->discoverStart($a);$http->json(['items'=>[['id'=>'remote-1','name'=>'Customer']]]);$s->discoverStep($a);$map=$s->map($a,'remote-1',$this->org(),true);$s->startSync($a,$map);$this->unthrottle();$http->json(['items'=>[['id'=>'one','name'=>'Original']]]);$s->syncStep($a,$map);$s->startSync($a,$map);$this->unthrottle();$record=$this->db->one('SELECT * FROM records');$payload=json_decode($record['payload'],true);$type=(int)$payload['template_id'];$payload['notes']='Manual edit committed while sync waits';$edit=\SimpleMSPDoc\Core\Database::connect(['dsn'=>getenv('TEST_DSN'),'username'=>getenv('TEST_DB_USER')?:'root','password'=>getenv('TEST_DB_PASSWORD')?:'']);$edit->connection()->beginTransaction();$edit->one('SELECT id FROM asset_types WHERE id=? FOR UPDATE',[$type]);$edit->run('UPDATE records SET title=?,payload=? WHERE id=?',['Latest manual title',json_encode($payload),$record['id']]);
  $env=array_merge(getenv(),['ACTION1_TEST_KEY'=>$key,'ACTION1_TEST_ACTOR'=>(string)$a->id,'ACTION1_TEST_MAPPING'=>(string)$map]);$p=proc_open([PHP_BINARY,'-c',php_ini_loaded_file(),dirname(__DIR__).'/Fixtures/action1-sync-worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);self::assertIsResource($p);fclose($pipes[0]);
  try{$thread=(int)trim(fgets($pipes[1]));$waiting=false;for($i=0;$i<100;$i++){if(($process=$this->db->one('SELECT INFO,TIME FROM information_schema.PROCESSLIST WHERE ID=?',[$thread]))&&str_contains($process['INFO']??'','SELECT id FROM asset_types')&&(int)$process['TIME']>=1){$waiting=true;break;}usleep(50000);}stream_set_blocking($pipes[2],false);self::assertTrue($waiting,'Worker did not wait on the template lock. '.stream_get_contents($pipes[2]).json_encode($this->db->all('SHOW PROCESSLIST')));$edit->connection()->commit();$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$status=proc_close($p);self::assertSame(0,$status,$err.$out);$p=null;$current=$this->db->one('SELECT * FROM records WHERE id=?',[$record['id']]);self::assertSame('Latest manual title',$current['title']);self::assertSame('Manual edit committed while sync waits',json_decode($current['payload'],true)['notes']);}
  finally{if($edit->connection()->inTransaction())$edit->connection()->rollBack();if(is_resource($p)){proc_terminate($p);foreach($pipes as $pipe)if(is_resource($pipe))fclose($pipe);proc_close($p);}}
 }
 public function testPaginatedDiscoveryDisabledAddonAndCredentialRotation(): void {
  [$a,$box,$http,$s]=$this->setupAddon();$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'client','client_secret'=>'secret']);$this->db->run('UPDATE action1_settings SET token_cipher=?,token_expires=?',[$box->seal(['access_token'=>'token'],'token'),time()+3600]);$s->discoverStart($a);$http->json(['items'=>[['id'=>'first','name'=>'First']],'next_page'=>'?from=50&limit=50']);self::assertTrue($s->discoverStep($a)['more']);self::assertSame(50,(int)$this->db->one('SELECT catalog_offset FROM action1_settings')['catalog_offset']);$this->unthrottle();$http->json(['items'=>[['id'=>'second','name'=>'Second']]]);self::assertFalse($s->discoverStep($a)['more']);self::assertStringContainsString('from=50',$http->requests[1]['url']);self::assertCount(2,$s->state($a)['organizations']);$s->map($a,'first',$this->org(),true);
  try{$s->saveSettings($a,['enabled'=>1,'region'=>'eu','client_id'=>'different','client_secret'=>'other']);self::fail('Tenant change allowed after mapping');}catch(HttpException $e){self::assertSame(409,$e->status);}$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_secret'=>'rotated']);$stored=$this->db->one('SELECT * FROM action1_settings');self::assertNull($stored['token_cipher']);self::assertSame('rotated',$box->open($stored['credentials'],'credentials')['client_secret']);$s->saveSettings($a,['region'=>'us']);$count=count($http->requests);try{$s->test($a);self::fail('Disabled integration made a request');}catch(HttpException $e){self::assertSame(422,$e->status);}self::assertCount($count,$http->requests);
 }
 public function testExpiredAccessTokenIsRenewedWithoutLeakingBodies(): void {
  [$a,$box,$http,$s]=$this->setupAddon();$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'client','client_secret'=>'secret']);$this->db->run('UPDATE action1_settings SET token_cipher=?,token_expires=?',[$box->seal(['access_token'=>'stale'],'token'),time()+3600]);$http->json(['message'=>'secret echoed by upstream'],401);try{$s->test($a);self::fail('Expected token renewal');}catch(Action1Error $e){self::assertSame(429,$e->status);self::assertStringNotContainsString('secret echoed',$e->getMessage());}self::assertNull($this->db->one('SELECT token_cipher FROM action1_settings')['token_cipher']);$this->unthrottle();$http->json(['access_token'=>'renewed','expires_in'=>3600]);try{$s->test($a);self::fail('Auth and GET should share request pacing');}catch(Action1Error $e){self::assertSame(429,$e->status);}$this->unthrottle();$http->json(['items'=>[]]);self::assertSame(0,$s->test($a)['count']);self::assertStringContainsString('Bearer renewed',implode(',',$http->requests[2]['headers']));
 }
 public function testPageFailureRollsBackAndDoesNotAdvanceCursor(): void {
  [$a,$box,$http,$s]=$this->setupAddon();$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'client','client_secret'=>'secret']);$this->db->run('UPDATE action1_settings SET token_cipher=?,token_expires=?',[$box->seal(['access_token'=>'token'],'token'),time()+3600]);$s->discoverStart($a);$http->json(['items'=>[['id'=>'remote-1','name'=>'Customer']]]);$s->discoverStep($a);$map=$s->map($a,'remote-1',$this->org(),true);$s->startSync($a,$map);$this->unthrottle();$http->json(['items'=>[['id'=>'one','name'=>'Valid'],['name'=>'Missing ID']],'next_page'=>'?from=50']);try{$s->syncStep($a,$map);self::fail('Invalid batch accepted');}catch(Action1Error $e){self::assertSame(502,$e->status);}self::assertSame([], $this->db->all('SELECT * FROM records'));self::assertSame(0,(int)$this->db->one('SELECT sync_offset FROM action1_mappings')['sync_offset']);
 }
 public function testCurrentNestedUpdateCountsAndInventoryRefreshWithoutOverwritingManualDetails(): void {
  [$a,$box,$http,$s]=$this->setupAddon();$s->saveSettings($a,['enabled'=>1,'region'=>'us','client_id'=>'client','client_secret'=>'secret']);$this->db->run('UPDATE action1_settings SET token_cipher=?,token_expires=?',[$box->seal(['access_token'=>'token'],'token'),time()+3600]);$s->discoverStart($a);$http->json(['items'=>[['id'=>'remote','name'=>'Customer']]]);$s->discoverStep($a);$map=$s->map($a,'remote',$this->org(),true);$templates=new \SimpleMSPDoc\Modules\Assets\TemplateService($this->db,new AuditService($this->db));$oldType=$templates->create($a,['name'=>'Old Action1 template','fields'=>[['name'=>'Action1 device name','type'=>'text']]]);$oldField=(int)$templates->get($oldType)['fields'][0]['id'];$this->db->run('UPDATE action1_settings SET template_id=?,field_map=?',[$oldType,json_encode(['name'=>$oldField])]);$s->startSync($a,$map);$this->unthrottle();
  $http->json(['items'=>[['id'=>'device','name'=>'PC','OS'=>['name'=>'Windows 11','version'=>'24H2'],'missing_updates'=>['critical'=>4,'other'=>7],'serial'=>'SER123','manufacturer'=>'Dell','RAM'=>'32 GB','disk'=>'1 TB SSD','CPU_name'=>'Core i7','CPU_size'=>'8 cores','MAC'=>'aa:bb:cc:dd:ee:ff','comment'=>'Action1 imported note']]]);$s->syncStep($a,$map);$r=$this->db->one("SELECT * FROM records WHERE type='asset'");$p=json_decode($r['payload'],true);$fields=json_decode($this->db->one('SELECT field_map FROM action1_settings')['field_map'],true);self::assertSame($oldType,(int)$p['template_id']);self::assertSame($oldField,(int)$fields['name']);self::assertSame('4',$p['values'][$fields['missing_critical_updates']]);self::assertSame('7',$p['values'][$fields['missing_other_updates']]);self::assertSame('SER123',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::effective($p)['serial_number']);self::assertSame('Action1 imported note',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($p));
  self::assertStringContainsString('Windows 11',$p['values'][$fields['OS']]);$p['details']=['ram'=>'64 GB'];(new \SimpleMSPDoc\Modules\Assets\AssetService($this->db,new AuditService($this->db)))->update($a,(int)$r['id'],['title'=>'PC','payload'=>$p]);
  $s->startSync($a,$map);$this->unthrottle();$http->json(['items'=>[['id'=>'device','name'=>'PC','RAM'=>'48 GB','missing_updates'=>['critical'=>0,'other'=>0]]]]);$s->syncStep($a,$map);$p=json_decode($this->db->one('SELECT payload FROM records WHERE id=?',[$r['id']])['payload'],true);self::assertSame('64 GB',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::effective($p)['ram']);self::assertSame('0',$p['values'][$fields['missing_critical_updates']]);self::assertSame('0',$p['values'][$fields['missing_other_updates']]);self::assertStringContainsString('fields=%2A',end($http->requests)['url']);
 }
